def solve(N):
    if N < 2:
        return 0

    perfect_powers = set()

    # Maximum exponent we need to consider
    # We need b such that 2^b <= N, so b <= log2(N)
    # For safety, we'll go up to 60 since 2^60 > 10^18
    max_exponent = 60

    for b in range(2, max_exponent + 1):
        # Find maximum a such that a^b <= N using binary search
        left, right = 1, 10**18
        max_base = 1

        # Binary search for the maximum a
        while left <= right:
            mid = (left + right) // 2
            # Calculate mid^b - we need to be careful about overflow
            try:
                power_val = pow(mid, b)
                if power_val <= N:
                    max_base = mid
                    left = mid + 1
                else:
                    right = mid - 1
            except OverflowError:
                right = mid - 1

        # Add all values a^b to our set
        a = 1
        while a <= max_base:
            power_val = pow(a, b)
            if power_val <= N:
