                        # First digit - any non-zero digit is valid
                        result = (result + dp(pos + 1, new_tight, digit, True)) % MOD
                    else:
                        # Check stepping condition: absolute difference must be exactly 1
                        if abs(digit - last_digit) == 1:
                            result = (result + dp(pos + 1, new_tight, digit, True)) % MOD

                return result

            return dp(0, True, -1, False)

        def subtract_one(s: str) -> str:
            digits = list(s)
            n = len(digits)

            # Handle the subtraction
            i = n - 1
            while i >= 0 and digits[i] == '0':
                digits[i] = '9'
                i -= 1

            if i >= 0:
                digits[i] = str(int(digits[i]) - 1)
            else:
                return "0"  # This means n was "1" or "0"

            result = ''.join(digits).lstrip('0')
            return result if result else "0"

        # For low-1, if low is "1", then low-1 is "0"
        if low == "1":
            low_minus_one = "0"
        else:
            low_minus_one = subtract_one(low)

        # Count stepping numbers from 1 to high minus stepping numbers from 1 to low-1
        count_high = count_stepping(high)
        count_low_minus = count_stepping(low_minus_one)

        result = (count_high - count_low_minus) % MOD
        return result if result >= 0 else result + MOD

class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def count_up_to(s):
            if not s:
                return 0
            n = len(s)

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, prev_digit, tight, started):
                # pos: current position
                # prev_digit: previous digit (0-9), -1 means no previous digit
                # tight: whether we are bounded by s
                # started: whether we have placed a non-zero digit

                if pos == n:
                    return 1 if started else 0

                result = 0
                limit = int(s[pos]) if tight else 9

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or (d > 0)

                    if not started and d == 0:
                        # Continue with leading zeros
                        result = (result + dp(pos + 1, prev_digit, new_tight, False)) % MOD
                    else:
                        # We have started or d > 0
                        if prev_digit == -1:
                            # First digit after leading zeros
                            result = (result + dp(pos + 1, d, new_tight, True)) % MOD
                        else:
                            # Check stepping condition: |d - prev_digit| == 1
                            if abs(d - prev_digit) == 1:
                                result = (result + dp(pos + 1, d, new_tight, True)) % MOD

                return result

            return dp(0, -1, True, False)

        # Count stepping numbers from 0 to high
        total_high = count_up_to(high)

        # For low-1, we need to handle the case properly
        def decrement_string(s):
            # Subtract 1 from string s
            result = []
            carry = 1  # Borrow of 1

            for i in range(len(s) - 1, -1, -1):
                digit = int(s[i]) - carry
                if digit < 0:
                    digit += 10
                    carry = 1
                else:
                    carry = 0
                result.append(str(digit))

            # Remove leading zeros
            result_str = ''.join(reversed(result))
            result_str = result_str.lstrip('0')

            return result_str if result_str else "0"

        # If low is "1", then low-1 is 0
        if low == "1":
            total_low_minus_1 = 0
        else:
            low_minus_1 = decrement_string(low)
            total_low_minus_1 = count_up_to(low_minus_1)

        return (total_high - total_low_minus_1 + MOD) % MOD

class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

