                        else:
                            # Check stepping condition: adjacent digits differ by exactly 1
                            if abs(digit - prev_digit) == 1:
                                result = (result + dp(pos + 1, new_tight, digit, True)) % MOD

                return result

            return dp(0, True, -1, False)

