            result += str(d)

        low_minus_one_str = result if result else "0"

        count_low_minus_one = count_up_to(low_minus_one_str) if low_minus_one_str != "0" else 0

        # For low = "1", low-1 = "0", and we want stepping numbers from 1 to high
        if low == "1":
            return count_high

        return (count_high - count_low_minus_one) % MOD

class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def count_up_to(n):
            digits = [int(d) for d in n]
            length = len(digits)

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, prev_digit, started):
                if pos == length:
                    return 1 if started else 0

                limit = digits[pos] if tight else 9
                result = 0

                for digit in range(0, limit + 1):
                    new_tight = tight and (digit == limit)
                    new_started = started or (digit > 0)

                    # Skip leading zeros
                    if not new_started and digit == 0:
                        result += dp(pos + 1, new_tight, prev_digit, new_started)
                    else:
                        if prev_digit == -1:  # First digit
                            result += dp(pos + 1, new_tight, digit, new_started)
                        else:
                            # Check stepping condition: absolute difference must be exactly 1
                            if abs(digit - prev_digit) == 1:
                                result += dp(pos + 1, new_tight, digit, new_started)

                return result % MOD

            return dp(0, True, -1, False)

        # Subtract one from low
        def subtract_one(s):
            digits = [int(d) for d in s]
            n = len(digits)

            # Start from rightmost digit
            i = n - 1
            while i >= 0 and digits[i] == 0:
                digits[i] = 9
                i -= 1

            if i < 0:
                return "0"  # All zeros

            digits[i] -= 1

            # Convert back to string (remove leading zeros)
            result = []
            for d in digits:
                result.append(str(d))

            result_str = ''.join(result).lstrip('0')
            return result_str if result_str else "0"

        # Handle the case where low is "1"
        low_minus_one = subtract_one(low)

        # Count stepping numbers in range [low, high]
        count_high = count_up_to(high)
        count_low_minus_one = count_up_to(low_minus_one)

        result = (count_high - count_low_minus_one) % MOD
        return result

