        for x in range(0, max_x + 1):
            remaining = d - x * L1
            if remaining <= 0:
                y_min = 0
            else:
                y_min = (remaining + L2 - 1) // L2

            # Try different numbers of type-2 sensors from minimum to maximum available
            y_max = K2 - t2
            if y_min > y_max:
                continue

            # For this x, we need to find the best y
            # We'll try all possible y values
            for y in range(y_min, y_max + 1):
                if x * L1 + y * L2 >= d:
                    new_t1 = t1 + x
                    new_t2 = t2 + y
                    new_cost = cost + x * C1 + y * C2

                    if (new_t1, new_t2) not in new_dp or new_dp[(new_t1, new_t2)] > new_cost:
                        new_dp[(new_t1, new_t2)] = new_cost

    dp = new_dp

